const body = $json.body || {};
const cas = Array.isArray(body.cas) ? body.cas : [];
const repetitions = Math.min(Math.max(parseInt(body.repetitions) || 3, 1), 5);
const campagneId = 'camp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
const modesValides = ['exact', 'juge', 'libre'];
const mode = modesValides.includes(body.mode) ? body.mode : 'exact';
const prompt = String(body.prompt || '');
const temperature = typeof body.temperature === 'number' ? body.temperature : 0.7;

const runs = [];
cas.forEach((c, i) => {
  for (let r = 1; r <= repetitions; r++) {
    runs.push({
      campagneId,
      casId: 'cas_' + (i + 1),
      entree: String(c.entree != null ? c.entree : ''),
      attendu: mode === 'libre' ? '' : String(c.attendu != null ? c.attendu : ''),
      repetition: r,
      mode,
      prompt,
      temperature
    });
  }
});

return [{ json: {
  campagneId,
  nom: String(body.nom || 'Campagne sans nom'),
  prompt,
  mode,
  temperature,
  repetitions,
  nbCas: cas.length,
  nbAppels: runs.length,
  runs
} }];

// --- Estimation des tokens ---------------------------------------------
// Calibre sur l execution 581 du 22/09/2026 (campagne camp_mucwi5f9_bqrg4) :
//   envoye  48915 caracteres -> 11403 tokens reels -> 4.3 caracteres par token
//   genere  31583 caracteres ->  5701 tokens reels -> 5.5 caracteres par token
// Le texte envoye (prompt structure, listes, termes techniques) se tokenise
// moins bien que la prose generee, d ou deux ratios differents.
// Une sortie non vide coute au moins un token, meme d un seul mot.
const CHARS_TOKEN_ENVOI = 4.3;
const CHARS_TOKEN_SORTIE = 5.5;
const estIn = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_ENVOI);
const estOut = s => { const n = String(s == null ? '' : s).length; return n ? Math.max(1, Math.round(n / CHARS_TOKEN_SORTIE)) : 0; };

const runs = $('Eclater les executions').all();

function extraireTexte(json) {
  if (!json) return '';
  if (typeof json.text === 'string') return json.text;
  const c = json.content;
  if (c && Array.isArray(c.parts)) {
    return c.parts.map(p => (p && typeof p.text === 'string') ? p.text : '').join('');
  }
  if (typeof c === 'string') return c;
  return '';
}

return $input.all().map((item, i) => {
  const r = runs[i] ? runs[i].json : {};
  const erreur = item.json && item.json.error ? String(item.json.error.message || item.json.error) : '';
  const sortie = String(extraireTexte(item.json)).trim();
  return { json: {
    campagneId: r.campagneId,
    casId: r.casId,
    entree: r.entree,
    attendu: r.attendu,
    repetition: r.repetition,
    mode: r.mode,
    prompt: r.prompt,
    sortie,
    erreur,
    tokensInExec: estIn(r.prompt) + estIn(r.entree),
    tokensOutExec: estOut(sortie)
  } };
});

