const base = $('Agreger la campagne').first().json;

// Le reviseur est un troisieme appel, une seule fois par campagne.
// 4650 tokens en entree a l execution 581, dont environ 675 pour son
// systemMessage une fois le reste estime a 4.3 caracteres par token.
const CHARS_TOKEN_ENVOI = 4.3;
const CHARS_TOKEN_JSON = 4.1;
const TOKENS_SYS_REVISEUR = 675;
const estIn = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_ENVOI);
const estJson = s => Math.round(String(s == null ? '' : s).length / CHARS_TOKEN_JSON);

function extraireTexte(json) {
  if (!json) return '';
  if (typeof json.text === 'string') return json.text;
  const c = json.content;
  if (c && Array.isArray(c.parts)) {
    return c.parts.map(p => (p && typeof p.text === 'string') ? p.text : '').join('');
  }
  if (typeof c === 'string') return c;
  return '';
}

function parser(txt) {
  const nettoye = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(nettoye); } catch (e) {}
  const d = nettoye.indexOf('{');
  const f = nettoye.lastIndexOf('}');
  if (d !== -1 && f > d) {
    try { return JSON.parse(nettoye.slice(d, f + 1)); } catch (e) {}
  }
  return null;
}

const brut = extraireTexte($input.first().json);
const analyse = parser(brut) || {};
const problemes = Array.isArray(analyse.problemes) ? analyse.problemes : [];
const changements = Array.isArray(analyse.changements) ? analyse.changements : [];

// --- Comptes finaux -----------------------------------------------------
const tarif = base.tarif || { modele: 'inconnu', prixIn: 0, prixOut: 0 };
const t = Object.assign({ execIn: 0, execOut: 0, jugeIn: 0, jugeOut: 0 }, base.tokens, {
  revIn: TOKENS_SYS_REVISEUR + estIn(base.prompt) + estIn(JSON.stringify(base.resumeAnalyse || [])),
  revOut: estJson(brut)
});

const usd = (tin, tout) => Math.round(((tin * tarif.prixIn + tout * tarif.prixOut) / 1e6) * 1e6) / 1e6;
const tokensEntree = t.execIn + t.jugeIn + t.revIn;
const tokensSortie = t.execOut + t.jugeOut + t.revOut;

// Le cout d un appel en production n est PAS le cout du banc : en production
// on paie l execution seule, pas le juge ni le reviseur, qui sont l outillage
// de test. C est ce chiffre qu il faut projeter a l echelle.
const appels = base.totalAppels || 1;
const coutParAppel = Math.round((usd(t.execIn, t.execOut) / appels) * 1e8) / 1e8;

const cout = {
  total: usd(tokensEntree, tokensSortie),
  execution: usd(t.execIn, t.execOut),
  jugement: usd(t.jugeIn, t.jugeOut),
  revision: usd(t.revIn, t.revOut),
  parAppelProduction: coutParAppel,
  modele: tarif.modele,
  prixIn: tarif.prixIn,
  prixOut: tarif.prixOut,
  estime: true
};

return [{ json: Object.assign({}, base, {
  diagnostic: String(analyse.diagnostic || ''),
  promptCorrige: String(analyse.promptCorrige || ''),
  confianceAnalyse: String(analyse.confiance || ''),
  problemes,
  changements,
  analyseJson: JSON.stringify({ problemes, changements, confiance: analyse.confiance || '' }),
  analyseOk: !!analyse.promptCorrige,
  tokens: t,
  tokensEntree,
  tokensSortie,
  cout,
  coutJson: JSON.stringify(cout)
}) }];

// Les resultats viennent d etre ecrits ligne a ligne.
// On revient a l item unique de l agregation pour lancer le reviseur une seule fois.
return [$('Agreger la campagne').first()];
